// Generated from the codegen function list: every function in the FMOD range
// 0x82E80000-0x83000000 (5912 functions) is wrapped. While FMOD EventSystemI::load
// (0x82FAECD8) runs on this thread and --fmod_diag=true, each wrapper logs:
//   - every call up to depth 3 (FMODTRACE), and
//   - any call at any depth whose returned r3 looks like a guest stack address
//     (0x70000000-0x7FFFFFFF) and differs from its own r3 argument (FMODSUS),
// which is how the bogus FMOD_RESULT 0x7018A5B0 seen in EventSystem::load is
// expected to show up. Pass-through otherwise.

#include <atomic>
#include <cstdint>

#include <rex/cvar.h>
#include <rex/hook.h>
#include <rex/logging.h>

REXCVAR_DECLARE(bool, fmod_diag);

namespace fmod_trace {
thread_local int g_depth = -1;  // -1: not inside EventSystemI::load
std::atomic<int> g_lines{0};
constexpr int kMaxLines = 20000;
inline bool stacky(uint32_t v) { return v >= 0x70000000u && v < 0x80000000u; }
inline void after(uint32_t addr, int d, uint32_t a3, uint32_t a4, uint32_t a5, uint32_t a6,
                  uint32_t sp, uint32_t r3) {
  bool sus = stacky(r3) && r3 != a3;
  if (!(d <= 3 || sus)) return;
  if (g_lines.fetch_add(1, std::memory_order_relaxed) >= kMaxLines) return;
  if (sus)
    REXAPU_INFO("FMODSUS d={} {:08X}({:08X},{:08X},{:08X},{:08X}) sp={:08X} -> {:08X}", d, addr,
                a3, a4, a5, a6, sp, r3);
  else
    REXAPU_INFO("FMODTRACE d={} {:08X}({:08X},{:08X},{:08X},{:08X}) sp={:08X} -> {:08X}", d, addr,
                a3, a4, a5, a6, sp, r3);
}
}  // namespace fmod_trace

#define FT_HOOK(name, addr)                                                            \
  REX_EXTERN(__imp__##name);                                                           \
  REX_HOOK_RAW(name) {                                                                 \
    if (fmod_trace::g_depth < 0) { __imp__##name(ctx, base); return; }                \
    int d = ++fmod_trace::g_depth;                                                     \
    uint32_t a3 = ctx.r3.u32, a4 = ctx.r4.u32, a5 = ctx.r5.u32, a6 = ctx.r6.u32,       \
             sp = ctx.r1.u32;                                                          \
    __imp__##name(ctx, base);                                                          \
    fmod_trace::g_depth = d - 1;                                                       \
    fmod_trace::after(addr, d, a3, a4, a5, a6, sp, ctx.r3.u32);                        \
  }

// Root: EventSystemI::load. Marks the thread as "inside load".
REX_EXTERN(__imp__sub_82FAECD8);
REX_HOOK_RAW(sub_82FAECD8) {
  bool top = fmod_trace::g_depth < 0 && REXCVAR_GET(fmod_diag);
  if (top) {
    fmod_trace::g_depth = 0;
    uint32_t data = ctx.r4.u32;
    const uint8_t* p = base + data;
    REXAPU_INFO("FMODTRACE load enter this={:08X} data={:08X} info={:08X} sp={:08X} "
                "first8={:02X}{:02X}{:02X}{:02X}{:02X}{:02X}{:02X}{:02X}",
                ctx.r3.u32, data, ctx.r5.u32, ctx.r1.u32, p[0], p[1], p[2], p[3], p[4], p[5],
                p[6], p[7]);
  }
  __imp__sub_82FAECD8(ctx, base);
  if (top) {
    REXAPU_INFO("FMODTRACE load leave -> {:08X}", ctx.r3.u32);
    fmod_trace::g_depth = -1;
  }
}

